        {"name": "Taxis & Uber", "type": "taxi", "scope": "intra_city", "description": "Licensed Paris taxis (white roof light) and Uber/Bolt are both widely available.", "coverage": "All of Paris and Île-de-France region", "price_info": "Base fare €2.60 + €1.12/km (day). CDG to central Paris: €55 flat rate (Right Bank) / €62 (Left Bank). Uber typically 10-20% cheaper.", "operating_hours": "24/7", "tips": "Use the official Taxi G7 app or Uber. Paris taxi fares to/from airports are fixed by law — never negotiate. The roof light is green when available, orange when occupied.", "booking_url": "https://www.g7.fr/en/", "tourist_pass": None},
