_UNIVERSAL_MONEY_TIPS = [
    {"title": "Always decline Dynamic Currency Conversion (DCC)", "body": "When paying by card abroad, if asked to pay in your home currency, always choose the local currency. DCC rates are typically 3-7% worse than your bank's rate."},
    {"title": "Use ATMs inside bank branches", "body": "Street-side ATMs are common targets for card skimming. ATMs inside bank branches or shopping malls are safer."},
    {"title": "Notify your bank before travelling", "body": "Tell your bank your travel dates and destinations to prevent fraud alerts blocking your cards abroad."},
    {"title": "Carry a backup payment method", "body": "Bring at least 2 cards from different networks (Visa + Mastercard). If one is blocked or lost, you have a backup."},
]


def _resolve_dest_currency(destination: str) -> dict | None:
    dest = destination.lower()
    for key, info in _DEST_CURRENCY.items():
        if _match_destination(dest, key):
            return info
    return None


def _get_nat_currency(nationality: str) -> tuple[str, str, str] | None:
    nat = nationality.lower().strip()
    if nat in _NATIONALITY_TO_CURRENCY:
        return _NATIONALITY_TO_CURRENCY[nat]
    for key, val in _NATIONALITY_TO_CURRENCY.items():
        if key in nat or nat in key:
            return val
    return None


def get_static_forex(request: TravelSearchRequest) -> dict | None:
    """Return instant forex info from lookup tables."""
    dest = request.destination.lower()
    local_currency = _resolve_dest_currency(request.destination)
    if not local_currency:
        return None

    # Find destination-specific forex data
    forex_data = None
    for key, data in _FOREX_TABLE.items():
        if _match_destination(dest, key):
            forex_data = data
            break

    # Build response
    result = {"local_currency": local_currency}

    # Exchange rates placeholder — will say "searching..." since static can't have live rates
    result["exchange_rates"] = [
        {"from_currency": "USD", "to_currency": local_currency["code"], "rate": None, "description": f"USD → {local_currency['code']}", "trend": "Live rate loading..."},
        {"from_currency": "EUR", "to_currency": local_currency["code"], "rate": None, "description": f"EUR → {local_currency['code']}", "trend": "Live rate loading..."},
    ]

    # Add home currency rate placeholder
    home = _get_nat_currency(request.nationality)
    if home and home[0] not in ("USD", "EUR") and home[0] != local_currency["code"]:
        result["exchange_rates"].append(
            {"from_currency": home[0], "to_currency": local_currency["code"], "rate": None, "description": f"{home[0]} → {local_currency['code']}", "trend": "Live rate loading..."}
        )

    if forex_data:
        result["card_acceptance"] = forex_data.get("card_acceptance")
        result["cash_advice"] = forex_data.get("cash_advice")
        result["atm_info"] = forex_data.get("atm_info")
        result["tipping"] = forex_data.get("tipping")
        result["exchange_locations"] = forex_data.get("exchange_locations", [])
        result["money_tips"] = forex_data.get("money_tips", []) + _UNIVERSAL_MONEY_TIPS
    else:
        result["money_tips"] = _UNIVERSAL_MONEY_TIPS

    result["source_urls"] = []
    return result
